      statusMessage.textContent = "";

      let firstInvalid = null;

      fields.forEach(({ input, message }) => {
        if (!validateField(input, message) && !firstInvalid) {
          firstInvalid = input;
        }
      });

      if (firstInvalid) {
        firstInvalid.focus();
        return;
      }

      statusMessage.textContent = "Thanks. Your support request is ready to send.";
      form.reset();
      fields.forEach(({ input }) => removeError(input));
    });
  </script>
