 <body>
   <a class="skip-link" href="#main-content">Skip to main content</a>

   <main id="main-content">
     <section class="support-card" aria-labelledby="support-title">
       <div class="hero">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our team</h1>
         <p class="intro">Tell us how to reach you and a support specialist will follow up as soon as possible.</p>
       </div>

       <form id="support-form" novalidate>
         <p class="required-note"><span class="required" aria-hidden="true">*</span> indicates a required field.</p>

         <div class="form-field">
           <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
           <input id="full-name" name="fullName" type="text" autocomplete="name" required>
         </div>

         <div class="form-field">
           <label for="email">Email address <span class="required" aria-hidden="true">*</span></label>
           <input id="email" name="email" type="email" autocomplete="email" required>
         </div>

         <div class="form-field">
           <label for="phone">Phone number <span class="optional">(optional)</span></label>
           <input id="phone" name="phone" type="tel" autocomplete="tel" aria-describedby="phone-help">
           <p id="phone-help" class="help-text">Use international format, for example +1 555 123 4567.</p>
         </div>

         <div class="form-actions">
           <button type="submit">Send support request</button>
           <p id="form-status" class="status-message" aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#support-form");
     const statusMessage = document.querySelector("#form-status");
     const fields = [
       {
         input: document.querySelector("#full-name"),
         message: "Error: Enter your full name."
       },
       {
         input: document.querySelector("#email"),
         message: "Error: Enter a valid email address, like name@example.com."
       }
     ];

     function removeError(input) {
       const errorId = `${input.id}-error`;
       const error = document.getElementById(errorId);
       if (error) {
         error.remove();
       }

       input.removeAttribute("aria-invalid");
       input.removeAttribute("aria-errormessage");
     }

     function showError(input, message) {
       const errorId = `${input.id}-error`;
       let error = document.getElementById(errorId);

       if (!error) {
         error = document.createElement("p");
         error.id = errorId;
         error.className = "error-message";
         input.insertAdjacentElement("afterend", error);
       }

       error.textContent = message;
       input.setAttribute("aria-invalid", "true");
       input.setAttribute("aria-errormessage", errorId);
     }

     function validateField(input, message) {
       if (input.validity.valid) {
         removeError(input);
         return true;
       }

       showError(input, message);
       return false;
     }

     fields.forEach(({ input, message }) => {
       input.addEventListener("input", () => {
         if (input.hasAttribute("aria-invalid")) {
           validateField(input, message);
         }
       });
     });

     form.addEventListener("submit", (event) => {
       event.preventDefault();
       statusMessage.textContent = "";

       let firstInvalid = null;

       fields.forEach(({ input, message }) => {
         if (!validateField(input, message) && !firstInvalid) {
           firstInvalid = input;
         }
       });

       if (firstInvalid) {
         firstInvalid.focus();
         return;
       }

       statusMessage.textContent = "Thanks. Your support request is ready to send.";
       form.reset();
       fields.forEach(({ input }) => removeError(input));
     });
   </script>
 </body>
 </html>

